'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rupee=v=>v===null||v===undefined||v===''?'Unknown':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(v));
const num=v=>v===null||v===undefined?'N/A':new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(Number(v));
const date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'Not supplied';
const badge=(v,c='')=>`<span class="pill ${c}">${esc(v)}</span>`;
let me,data,masterData=[],page='overview',workspace='demo',moduleTab='',seq=0;
const today=new Date().toISOString().slice(0,10);const yr=Number(today.slice(0,4))-(Number(today.slice(5,7))<4?1:0);
let filters={start:yr+'-04-01',end:today};
const pages={overview:['▦','Executive Overview','FINANCE CONTROL','Earnings, obligations, liquidity and the actions that need attention.'],revenue:['◫','Revenue & Billing','REVENUE CONTROLS','Bills, service activity and accounting revenue remain distinct.'],receivables:['◷','Receivables & Claims','MONEY TO COLLECT','Follow claim progress, allocate collections and prioritise overdue actions.'],payables:['▤','Payables & Procurement','MONEY TO PAY','Supplier liabilities, three-way matching and proposed payment priorities.'],treasury:['◇','Bank, Cash & Forecast','TREASURY WORKSPACE','Reconcile bank and book movements; explore a source-backed 13-week forecast.'],expenses:['⌁','Expenses & Payroll','COST CONTROL','Incurred expense, cash paid, consultant contracts and shared allocations.'],inventory:['✚','Inventory & Pharmacy','STOCK & MEDICINE FINANCE','Purchases are stock receipts; consumption is cost. MRP is never valuation.'],assets:['⌂','Assets & Debt','CAPITAL & FINANCING','Asset carrying values, capex, principal movements and repayment schedules.'],statements:['≡','Profitability & Statements','ACCOUNTING AUTHORITY','Reviewed ledgers support accounting results; incomplete inputs stay visible.'],budget:['▥','Budget & Scenarios','FORWARD VIEW','Compare compatible actuals with budget and maintain separate assumptions.'],gaps:['◎','Financial Gaps','EXCEPTION CENTRE','Evidence, ownership and next actions. Exceptions are review items, not proof of loss.'],close:['☑','Month-End Close','CLOSE & REVIEW','Evidence, independent sign-off, period locks and versioned issued reports.'],setup:['⇧','Imports & Settings','FLEXIBLE DATA SETUP','Begin with a few registers; add sources, entities and categories as needed.']};
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'X-Navin-Request':'1',...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}});if(!r.ok){let b;try{b=await r.json()}catch{b={detail:r.statusText}}if(r.status===401&&path!='/api/login')showLogin();throw Error(typeof b.detail==='string'?b.detail:JSON.stringify(b.detail))}return r.json()}
const scoped=p=>p+(p.includes('?')?'&':'?')+'workspace='+workspace;
const post=(p,b={})=>api(scoped(p),{method:'POST',body:JSON.stringify(b)});
function toast(message,error=false){$('#toast').textContent=message;$('#toast').style.background=error?'#943f3b':'#174b3d';$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,6000)}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
$('#closeModal').onclick=()=>$('#modal').close();
function showLogin(){$('#login').hidden=false;$('#workspace').hidden=true}
function options(rows,current='',empty='All'){return (empty===null?'':`<option value="">${esc(empty)}</option>`)+rows.map(x=>{const v=typeof x==='string'?x:x.key;const name=typeof x==='string'?x:x.name;return `<option value="${esc(v)}" ${v===current?'selected':''}>${esc(name)}</option>`}).join('')}
const master=(kind)=>masterData.filter(x=>x.kind===kind);
const name=(kind,key)=>master(kind).find(x=>x.key===key)?.name||key||'Unassigned';
const exportButtons=scope=>`<div class="export-buttons"><button data-export="${scope}" data-format="csv">↓ CSV</button><button data-export="${scope}" data-format="xlsx">↓ Excel</button></div>`;
const card=(title,subtitle,body,scope='')=>`<section class="card"><div class="card-head"><div><h3>${title}</h3><p>${subtitle}</p></div>${scope?exportButtons(scope):''}</div>${body}</section>`;
function allowedPages(){if(me.role==='collections')return ['overview','revenue','receivables','gaps','setup'];if(me.role==='procurement')return ['overview','payables','inventory','gaps','setup'];if(me.role==='reviewer')return Object.keys(pages).filter(k=>k!=='expenses');return Object.keys(pages)}
async function start(){try{me=await api('/api/me');$('#login').hidden=true;$('#workspace').hidden=false;$('#userInfo').innerHTML=`${esc(me.username)}<small>${esc(me.role)} access</small>`;$('#nav').innerHTML=allowedPages().map(k=>`<button data-nav="${k}"><span class="icon">${pages[k][0]}</span>${pages[k][1]}</button>`).join('');$$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));await navigate(page)}catch(e){showLogin()}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();$('#loginError').textContent='';await start()}catch(err){$('#loginError').textContent=err.message}};
$('#logout').onclick=async()=>{await post('/api/logout');showLogin()};$('#uploadShortcut').onclick=()=>{moduleTab='import';navigate('setup')};$('#workspaceMode').onchange=e=>{workspace=e.target.value;filters={start:yr+'-04-01',end:today};moduleTab='';navigate(page)};
async function navigate(next){page=next;const current=++seq;$('#content').innerHTML='<div class="loading">Loading financial records…</div>';$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));const p=pages[page];$('#pageTitle').textContent=p[1];$('#crumb').textContent=p[1];$('#pageEyebrow').textContent=p[2];$('#pageSubtitle').textContent=p[3];$('#pageActions').innerHTML=exportButtons({overview:'management_pack',revenue:'records',receivables:'receivables',payables:'payables',treasury:'forecast',expenses:'expenses',inventory:'inventory',assets:'assets',statements:'statements',budget:'budget',gaps:'exceptions',close:'management_pack',setup:'data_setup'}[page]);try{const results=await Promise.all([api('/api/analytics?'+new URLSearchParams({...filters,workspace})),api(scoped('/api/masters'))]);if(current!==seq)return;[data,masterData]=results;renderFilters();await ({overview:overview,revenue:revenue,receivables:receivables,payables:payables,treasury:treasury,expenses:expenses,inventory:inventory,assets:assets,statements:statements,budget:budget,gaps:gaps,close:close,setup:setup}[page])();bind()}catch(e){$('#content').innerHTML=`<div class="notice">${esc(e.message)}</div>`;toast(e.message,true)}}
function renderFilters(){$('#filters').hidden=false;$('#filters').innerHTML=`<label>ENTITY<select data-filter="entity_id">${options(master('entity'),filters.entity_id,'All legal entities')}</select></label><label>BRANCH<select data-filter="branch_id">${options(master('branch'),filters.branch_id,'All authorised branches')}</select></label><label>FROM<input data-filter="start" type="date" value="${esc(filters.start)}"></label><label>TO / AS OF<input data-filter="end" type="date" value="${esc(filters.end)}"></label><button id="moreFilters">＋ Filters</button><button id="savedView">Save view</button><button id="resetFilters">Reset</button><div id="extraFilters" class="form-grid" hidden style="flex-basis:100%;width:100%"><label>Department<select data-filter="department_id">${options(master('department'),filters.department_id,'All departments')}</select></label><label>Panel<select data-filter="panel_id">${options(master('panel'),filters.panel_id,'All panels')}</select></label><label>Vendor<select data-filter="vendor_id">${options(master('vendor'),filters.vendor_id,'All vendors')}</select></label><label>Recorded status<input data-filter="status" value="${esc(filters.status)}"></label><label class="full">Search document, patient or admission<input data-filter="search" value="${esc(filters.search)}"></label><div id="viewList"></div></div>`;$$('[data-filter]').forEach(el=>el.onchange=()=>{filters[el.dataset.filter]=el.value;navigate(page)});$('#moreFilters').onclick=async()=>{$('#extraFilters').hidden=!$('#extraFilters').hidden;const views=await api('/api/views');$('#viewList').innerHTML=views.map(v=>`<button data-view="${v.id}" class="small">${esc(v.name)}</button>`).join('');$$('[data-view]').forEach(b=>b.onclick=()=>{const v=views.find(x=>x.id===Number(b.dataset.view));workspace=v.filters.workspace||workspace;$('#workspaceMode').value=workspace;filters={...v.filters};delete filters.workspace;navigate(page)})};$('#resetFilters').onclick=()=>{filters={start:yr+'-04-01',end:today};navigate(page)};$('#savedView').onclick=()=>{modal('Save this filter context',`<form id="viewForm" class="stack"><label>View name<input name="name" required></label><button class="primary">Save view</button></form>`);$('#viewForm').onsubmit=async e=>{e.preventDefault();await post('/api/views',{name:new FormData(e.target).get('name'),filters:{...filters,workspace}});$('#modal').close();toast('View saved')}}}
function banner(){return `<div class="notice ${workspace==='demo'?'demo':'info'}"><span>${workspace==='demo'?'◇':'◈'}</span><div><strong>${workspace==='demo'?'Synthetic demonstration workspace':'Real finance records'}</strong>${workspace==='demo'?'All figures and people here are synthetic. Imports only enter the separate real workspace.':'No original hospital/accounting exports were supplied with the specification. Source-specific mappings require actual-file validation.'} Period ${date(data.filters.start)} – ${date(data.filters.end)}. Balances are as of the end date; flows use posting dates.</div></div>`}
function metric(key,label,value,help,source=''){return `<button class="metric" data-metric="${key}"><div class="metric-label">${esc(label)}<span>↗</span></div><div class="metric-value">${rupee(value)}</div><div class="metric-meta">${date(data.filters.start)} – ${date(data.filters.end)}<br>${esc(source||'Source-backed; missing inputs stay unknown')}</div><div class="help">${esc(help)}</div></button>`}
function table(rows,columns,{recordClick=false}={}){return `<div class="table-wrap"><table class="plain-table record-table"><thead><tr>${columns.map(c=>`<th ${c.money?'class="number"':''}>${esc(c.label||c.key.replaceAll('_',' '))}</th>`).join('')}<th>Evidence</th></tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(c=>`<td ${c.money?'class="number"':''}>${c.render?c.render(r[c.key],r):c.money?rupee(r[c.key]):c.date?date(r[c.key]):esc(typeof r[c.key]==='object'?JSON.stringify(r[c.key]):r[c.key]??'Unknown')}</td>`).join('')}<td>${r.id&&recordClick?`<button class="small" data-record="${r.id}">#${r.id} · Source</button>`:r.record_ids?`<button class="small" data-records="${r.record_ids.join(',')}">View ${r.record_ids.length} records</button>`:'—'}</td></tr>`).join('')||`<tr><td colspan="${columns.length+1}">No records in this scope. Source unavailable is not a zero discrepancy.</td></tr>`}</tbody></table></div>`}
const recordColumns=[{key:'doc_id',label:'Document'},{key:'kind',label:'Register',render:v=>esc(me.source_types[v]?.name||v)},{key:'branch_id',label:'Branch',render:v=>esc(name('branch',v))},{key:'date',date:true},{key:'amount',money:true},{key:'status'}];
function rowsOf(kinds,balance=false){return (balance?data.asof_records:data.records).filter(r=>kinds.includes(r.kind))}
function bind(){$$('[data-export]').forEach(b=>b.onclick=()=>location.href='/api/export/'+b.dataset.export+'?'+new URLSearchParams({...filters,workspace,format:b.dataset.format}));$$('[data-record]').forEach(b=>b.onclick=()=>openRecord(Number(b.dataset.record)));$$('[data-records]').forEach(b=>b.onclick=()=>drill(b.dataset.records.split(',').filter(Boolean).map(Number),'Source evidence'));$$('[data-metric]').forEach(b=>b.onclick=()=>drillMetric(b.dataset.metric));$$('[data-exception]').forEach(b=>b.onclick=()=>reviewException(b.dataset.exception));$$('[data-navto]').forEach(b=>b.onclick=()=>navigate(b.dataset.navto));$$('[data-import]').forEach(b=>b.onclick=()=>openImport(Number(b.dataset.import)));$$('[data-branch]').forEach(b=>b.onclick=()=>{filters.branch_id=b.dataset.branch;navigate(page)});$$('[data-template]').forEach(b=>b.onclick=()=>location.href='/api/templates/'+b.dataset.template);}
async function openRecord(id){try{const r=await api('/api/records/'+id);modal(`${me.source_types[r.kind]?.name||r.kind} · ${r.doc_id}`,`<div class="notice info">${esc(name('branch',r.branch_id))} · ${date(r.date)} · ${esc(r.workspace)} workspace · Original values are immutable.</div><div class="form-grid">${Object.entries(r.fields).map(([k,v])=>`<div><label>${esc(me.source_types[r.kind]?.fields[k]||k)}</label><p>${esc(v??'Unknown')}</p></div>`).join('')}</div><div class="section-title">RECEIPT / PAYMENT ALLOCATIONS</div>${table(r.allocations,[{key:'related_document'},{key:'amount',money:true},{key:'active'}])}<div class="section-title">ORIGINAL SOURCE</div><p class="fine">Import ${r.import_id??'Reviewed manual / synthetic'} · ${esc(r.sheet)} · row ${r.row_no??'—'}</p><pre>${esc(JSON.stringify(r.original,null,2))}</pre><div class="toolbar">${me.role!=='reviewer'?'<button id="correctRecord">Request correction / void</button>':''}</div>`);if($('#correctRecord'))$('#correctRecord').onclick=()=>sensitiveForm('record_void',{id:r.id},r.branch_id,'Void original and enter corrected document after approval. Original source remains retained.')}catch(e){toast(e.message,true)}}
function drill(ids,title){const rows=data.asof_records.filter(r=>ids.includes(r.id));modal(title,`<p class="fine">${rows.length} source records · Same entity/branch/date/filter context. Balances may include records before the flow period.</p>${table(rows,recordColumns,{recordClick:true})}`);bind()}
function drillMetric(key){let ids=[];if(['accounting_revenue','ebitda','net_result','operating_expenses'].includes(key))ids=data.statements.record_ids;else if(key==='receivables')ids=data.receivables.map(r=>r.id);else if(key==='payables')ids=data.payables.map(r=>r.id);else if(key==='bank_verified_balance')ids=data.bank_balances.flatMap(r=>r.record_ids);else if(key==='inventory_value')ids=data.inventory.flatMap(r=>r.record_ids);else if(key==='debt_principal')ids=data.loans.flatMap(r=>r.record_ids);else ids=rowsOf(key==='operational_billing'?['billing']:['billing','service','pharmacy']).map(r=>r.id);drill(ids,key.replaceAll('_',' '))}
function bars(rows,key,label){const max=Math.max(1,...rows.map(r=>Math.abs(Number(r[key]||0))));if(!rows.length)return '<div class="empty-chart"><strong>No source-backed trend available</strong><p>Import records or explore the separate synthetic demo.</p></div>';return rows.map(r=>`<div class="bar-row clickable" data-records="${(r.record_ids||[]).join(',')}"><span>${esc(label==='branch_id'?name('branch',r[label]):r[label])}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.abs(Number(r[key]||0))/max*100}%"></div></div><span class="bar-value">${rupee(r[key])}</span></div>`).join('')}
function overview(){const k=data.kpis;$('#content').innerHTML=banner()+`<div class="metric-grid">${metric('accounting_revenue','Accounting revenue',k.accounting_revenue,'Earned revenue in the reviewed books; not cash received.',data.statements.accounting_complete?'Complete mapped accounting source':'Accounting coverage incomplete')}${metric('bank_verified_balance','Recorded bank & cash',k.bank_verified_balance,'Latest supplied snapshots; check their dates and account coverage.','Bank statement / cash-count snapshots')}${metric('receivables','Money to collect',k.receivables,'Receivables: valid bills still owed after allocated settlements.','Bill and adjustment rollforward · as of period end')}${metric('payables','Money to pay',k.payables,'Payables: supplier invoices still owed; transfers are not expenses.','Invoice rollforward · as of period end')}</div><div class="metric-grid">${metric('ebitda','EBITDA',k.ebitda,'Operating result before depreciation, interest and tax.',data.statements.accounting_complete?'Balanced mapped books; not audited certification':'Unavailable until books are complete')}${metric('net_result','Accounting net result',k.net_result,'Result after recorded depreciation, finance cost and tax.','Branch aggregation, not consolidation')}${metric('inventory_value','Recorded inventory value',k.inventory_value,'Stock value from recorded costs; purchases differ from consumption.','Signed inventory cost movements')}${metric('operational_billing','Operational net billing',k.operational_billing,'Final hospital bills. Never added to accounting revenue.','Final-bill posting period')}</div><div class="grid-2">${card('Monthly billing & collection activity','Final bills and receipts are separate measures',`<div class="card-body">${bars(data.monthly,'operational_billing','month')}</div>`)}${card('Branch comparison','Operational billing · same filter context',`<div class="card-body">${bars(data.branches,'operational_billing','branch_id')}</div>`)}</div>${card('Management action priorities','Exposure figures can overlap; there is no summed “total loss”.',exceptionTable(data.exceptions.filter(x=>!['resolved','suppressed','explained'].includes(x.status)).slice(0,8)),'exceptions')}${card('Branch financial comparison','Aggregation only; click evidence to inspect the records.',table(data.branches,[{key:'branch_id',render:v=>esc(name('branch',v))},{key:'accounting_revenue',money:true},{key:'operational_billing',money:true},{key:'documents'}]),'branches')}`}
function revenue(){$('#content').innerHTML=banner()+`<div class="metric-grid">${metric('operational_billing','Net patient billing',data.kpis.operational_billing,'Final bill amount after validated discounts/credits.','Billing register')}${metric('accounting_revenue','Accounting revenue',data.kpis.accounting_revenue,'Reviewed ledger revenue; do not add operational billing.','Accounting posting basis')}${metric('operational_contribution','Partial operational contribution',data.kpis.operational_contribution,'Available costs only; missing heads/attribution prevent final profit.','Operational records; completeness unverified')}${metric('known_operational_cost','Known operational direct costs',data.kpis.known_operational_cost,'Actual cost amounts only; MRP and purchase rates are not inferred.','Service / pharmacy cost detail')}</div>${card('Revenue reconciliation bridge','Differences remain unexplained until source scopes and credits are reconciled.',table([data.revenue_bridge],[{key:'accounting_revenue',money:true},{key:'operational_billing',money:true},{key:'difference',money:true},{key:'label'}]))}${card('Patient bills & admissions','UHID is a patient key; branch + admission ID identifies an admission.',table(rowsOf(['billing']),[{key:'bill_id'},{key:'branch_id',render:v=>esc(name('branch',v))},{key:'uhid'},{key:'admission_id'},{key:'patient'},{key:'panel_id',render:v=>esc(name('panel',v))},{key:'date',date:true},{key:'gross',money:true},{key:'discount',money:true},{key:'amount',money:true}],{recordClick:true}),'records')}${card('Department / operational contribution','Detail service revenue is not added to final patient bills.',table(data.departments,[{key:'department_id',render:v=>esc(name('department',v))},{key:'operational_billing',money:true},{key:'detail_revenue',money:true},{key:'eligible_contribution',money:true},{key:'missing_cost_lines'}]),'departments')}${card('Encounter and service controls','Unbilled activity requires a performed/expected-billing field and a reliable linked bill.',table(rowsOf(['service','encounter']),recordColumns,{recordClick:true}))}`}
function allocationForm(kind){const cash=rowsOf(kind==='ar'?['receipt']:['payment'],true),targets=kind==='ar'?data.receivables:[...data.payables,...data.expenses];return `<form id="allocateForm" class="form-grid"><label>${kind==='ar'?'Receipt / advance / authorised refund':'Payment'}<select name="cash_id" required>${options(cash.map(r=>({key:String(r.id),name:`#${r.id} ${r.doc_id} · ${rupee(r.amount)}`})),'','Select cash record')}</select></label><label>${kind==='ar'?'Patient bill':'Invoice / incurred expense'}<select name="document_id" required>${options(targets.map(r=>({key:String(r.id),name:`#${r.id} ${r.doc_id} · ${rupee(r.outstanding??r.unpaid_amount)}`})),'','Select document')}</select></label><label>Signed amount to allocate<input name="amount" type="number" step=".01" required></label><label>Evidence / allocation note<input name="notes" required></label><button class="primary" ${me.role==='reviewer'?'disabled':''}>Propose allocation</button></form>`}
function bindAllocation(){$('#allocateForm').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));b.cash_id=Number(b.cash_id);b.document_id=Number(b.document_id);await post('/api/allocations',b);toast('Allocation awaits an independent finance reviewer');e.target.reset()}catch(err){toast(err.message,true)}}}
function receivables(){$('#content').innerHTML=banner()+`<div class="metric-grid">${metric('receivables','Receivables',data.kpis.receivables,'Money others owe after actual allocations; approval is not collection.','As-of bill/credit/receipt rollforward')}${metric('unallocated_receipts','Unallocated receipts',data.kpis.unallocated_receipts,'Cash received or advances awaiting a reviewed bill allocation.','Receipts excluding transfers and loan receipts')}${metric('operational_billing','Period net billing',data.kpis.operational_billing,'Credit and self-pay bills remain separately identifiable.','Final bill posting dates')}<div class="metric"><div class="metric-label">DSO · collection days</div><div class="metric-value">${num(data.kpis.dso)}</div><div class="help">Closing receivables ÷ compatible verified credit revenue × period days. Not calculated from incomplete inputs.</div><div class="metric-meta">As of ${date(data.filters.end)}</div></div></div>${card('Claim lifecycle & receivable ageing','Age since billing differs from days overdue; due-date absence remains unknown.',table(data.receivables,[{key:'bill_id'},{key:'patient'},{key:'panel_id',render:v=>esc(name('panel',v))},{key:'claim_status'},{key:'payment_status'},{key:'approved_amount',money:true},{key:'settlements',money:true},{key:'outstanding',money:true},{key:'age_bucket'},{key:'days_overdue'},{key:'owner'},{key:'next_action'}],{recordClick:true}),'receivables')}${card('Allocate partial or combined receipts','One receipt can be allocated across several bills. Each proposal requires independent review.',`<div class="card-body">${allocationForm('ar')}</div>`)}${card('Receipts, advances and refunds','Patient advances and loan receipts are not automatically earned revenue.',table(rowsOf(['receipt'],true),recordColumns,{recordClick:true}))}`;bindAllocation()}
function payables(){$('#content').innerHTML=banner()+`${card('Supplier liability & proposed payment priority','Priority: disputed items require review, clinical-critical suppliers, then recorded due date. No payments are executed.',table(data.payables,[{key:'invoice_id'},{key:'vendor_id',render:v=>esc(name('vendor',v))},{key:'amount',money:true},{key:'settlements',money:true},{key:'outstanding',money:true},{key:'due_date',date:true},{key:'days_overdue'},{key:'three_way_match'},{key:'payment_priority'}],{recordClick:true}),'payables')}${card('Allocate payments / advances','Payments settle liabilities; inventory receipts and invoices are not automatically operating expense.',`<div class="card-body">${allocationForm('ap')}</div>`)}${card('Procurement source documents','POs, goods receipts, invoices, credit notes and payments are kept separately.',table(rowsOf(['purchase_order','goods_receipt','invoice','payment','ap_adjustment'],true),recordColumns,{recordClick:true}))}`;bindAllocation()}
function treasury(){const forecast=data.forecast.find(x=>x.scenario===(moduleTab||'base'))||data.forecast[0];$('#content').innerHTML=banner()+card('Recorded bank balances vs book cash','Latest bank/cash snapshots show their verification dates. Missing openings or closing snapshots are unknown.',table(data.bank_balances,[{key:'bank_account_id',render:v=>esc(name('bank_account',v))},{key:'branch_id',render:v=>esc(name('branch',v))},{key:'verified_date',date:true},{key:'verified_balance',money:true},{key:'book_balance',money:true},{key:'movement_rollforward',money:true},{key:'difference',money:true}]),'bank_balances')+card('Bank reconciliation workspace','Reference + exact amount + date suggests matches; all decisions need independent review.',`<div class="card-body"><form id="bankForm" class="form-grid"><label>Bank movement<select name="bank_id" required>${options(data.bank_transactions.map(r=>({key:String(r.id),name:`#${r.id} ${r.doc_id} · remaining ${rupee(r.unmatched_amount)}`})),'','Select bank record')}</select></label><label>Book movement<select name="book_id" required>${options(data.book_transactions.map(r=>({key:String(r.id),name:`#${r.id} ${r.doc_id} · remaining ${rupee(r.unmatched_amount)}`})),'','Select book record')}</select></label><label>Signed partial match amount<input name="amount" type="number" step=".01" required></label><label>Review note<input name="notes" required></label><button class="primary">Propose reviewed match</button></form></div>${table(data.bank_suggestions,[{key:'bank_id'},{key:'candidate_book_ids'},{key:'amount',money:true},{key:'status'}])}`)+card('Bank movement evidence','Transfer and loan movements remain cash movements, not income/expense.',table(data.bank_transactions,[{key:'doc_id'},{key:'reference'},{key:'date',date:true},{key:'amount',money:true},{key:'matched_amount',money:true},{key:'unmatched_amount',money:true}],{recordClick:true}),'bank_transactions')+`<div class="tabs">${['base','delayed','stress'].map(x=>`<button class="${forecast.scenario===x?'active':''}" data-scenario="${x}">${x[0].toUpperCase()+x.slice(1)} cash scenario</button>`).join('')}</div>`+card('Rolling 13-week cash forecast','Editable assumptions are separate from actuals. Linked invoices/commitments are not counted twice; incomplete obligation coverage remains explicit.',table(forecast.rows,[{key:'week'},{key:'start',date:true},{key:'opening',money:true},{key:'expected_inflow',money:true},{key:'expected_outflow',money:true},{key:'closing',money:true},{key:'document_ids'}]),'forecast');$('#bankForm').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));b.bank_id=Number(b.bank_id);b.book_id=Number(b.book_id);await post('/api/bank-matches',b);toast('Bank match proposed for review')}catch(err){toast(err.message,true)}};$$('[data-scenario]').forEach(b=>b.onclick=()=>{moduleTab=b.dataset.scenario;navigate('treasury')})}
function expenses(){$('#content').innerHTML=banner()+card('Incurred expense, payments and accruals','Accrued balance means recorded expense incurred but not yet paid. Cash paid is not a second expense.',table(data.expenses,[{key:'doc_id'},{key:'kind'},{key:'employee_id'},{key:'consultant_id'},{key:'department_id'},{key:'amount',money:true},{key:'paid_amount',money:true},{key:'unpaid_amount',money:true},{key:'contract_expected',money:true},{key:'evidence'}],{recordClick:true}),'expenses')+card('Shared-cost allocations','Explicit revenue, bed-days, headcount, floor-area or usage driver; allocation does not create an extra recorded expense.',table(data.shared_allocations,[{key:'rule_id'},{key:'driver'},{key:'period'},{key:'pool',money:true},{key:'allocations'},{key:'unallocated',money:true}]),'shared_allocations')+`<div class="toolbar"><button class="primary" id="contractAdd">Add consultant contract</button><button id="sharedAdd">Add shared-cost rule</button></div>`;$('#contractAdd').onclick=()=>ruleForm('consultant');$('#sharedAdd').onclick=()=>ruleForm('shared_cost')}
function inventory(){$('#content').innerHTML=banner()+card('Recorded stock and financial exposure','Signed recorded costs only. Counts are snapshots, not stock receipts. Purchases and consumption remain separate.',table(data.inventory,[{key:'branch_id',render:v=>esc(name('branch',v))},{key:'store_id'},{key:'item_id'},{key:'batch_id'},{key:'closing_quantity'},{key:'recorded_inventory_value',money:true},{key:'physical_count_difference'},{key:'expiry_date',date:true},{key:'expiry_exposure',money:true}]),'inventory')+card('Main and Secondary Pharmacy profitability','Gross profit and weighted margin use only medicine lines with known actual COGS; missing costs stay unknown.',table(data.pharmacy,[{key:'source'},{key:'net_sales',money:true},{key:'recorded_cogs',money:true},{key:'eligible_sales',money:true},{key:'gross_profit',money:true},{key:'margin',render:v=>v===null?'N/A':num(v)+'%'},{key:'missing_cost_lines'},{key:'returns',money:true}]),'pharmacy')+card('Inventory / medicine source records','Transfer counterparts must reconcile; inventory MRP is not inferred.',table(rowsOf(['inventory','pharmacy'],true),recordColumns,{recordClick:true}))}
function assets(){$('#content').innerHTML=banner()+card('Asset register & capex','Recorded depreciation differs from a rule-based estimate. Principal repayments do not become operating expenses.',table(data.assets,[{key:'asset_id'},{key:'branch_id'},{key:'amount',money:true},{key:'recorded_depreciation',money:true},{key:'estimated_depreciation',money:true},{key:'carrying_amount',money:true},{key:'approved_budget',money:true},{key:'capex_variance',money:true}],{recordClick:true}),'assets')+card('Debt rollforward & repayments','Opening + drawdowns − principal repayments = closing principal. Interest/fees remain separate.',table(data.loans,[{key:'loan_id'},{key:'opening',money:true},{key:'drawdowns',money:true},{key:'principal_repaid',money:true},{key:'closing_principal',money:true},{key:'finance_cost',money:true},{key:'schedule'}]),'loans')+card('Tax & statutory tracking','User-approved treatment and deadlines only; no filing, legal rate defaults or certification.',table(data.statutory,[{key:'liability_id'},{key:'liability',money:true},{key:'paid',money:true},{key:'credits',money:true},{key:'outstanding',money:true},{key:'due_date',date:true}]),'statutory')+card('Capital, debt and statutory evidence','Security, covenants, leases and deposits can be retained as user-entered fields; advanced accounting needs reviewed policies.',table(rowsOf(['asset','loan','statutory'],true),recordColumns,{recordClick:true}))}
function statements(){const s=data.statements;$('#content').innerHTML=banner()+`<div class="notice ${s.accounting_complete?'info':''}"><div><strong>${s.accounting_complete?'Reviewed accounting coverage declared complete':'Accounting statements incomplete'}</strong>${esc(s.limitation)} ${esc(s.aggregation_label)}</div></div><div class="metric-grid">${metric('accounting_revenue','Accounting revenue',s.revenue,'Reviewed ledger category; never operational revenue added again.',s.basis)}${metric('ebitda','EBITDA',s.ebitda,'Revenue − direct cost − operating expenses.',s.basis)}${metric('net_result','Net accounting result',s.net_result,'EBITDA less depreciation, finance cost and tax.',s.basis)}${metric('operational_contribution','Operational contribution',data.kpis.operational_contribution,'Partial source-supported costs only; not audited net profit.','Operational basis')}</div>`+card('Accounting P&L categories','Each category drills to the mapped journal or compatible trial-balance records.',table(s.rows,[{key:'category'},{key:'amount',money:true}]),'statements')+card('Supported balance sheet','Only available with complete openings, balanced books and reviewed classifications.',table([s.balance_sheet],[{key:'available'},{key:'assets',money:true},{key:'liabilities',money:true},{key:'equity_including_result',money:true},{key:'difference',money:true}]))+`<div class="notice">Accounting cash-flow statement: ${esc(data.cash_flow_statement.reason)} Use the bank/forecast workspace for explicitly labelled cash movements and forecasts.</div>`+card('Operational hospital economics','Ratios are only shown where the numerator and denominator are supplied.',table([data.economics],[{key:'revenue_per_discharge',money:true},{key:'occupied_bed_days'},{key:'available_bed_days'},{key:'occupancy'},{key:'label'}]))+card('Related-party and interbranch evidence','Aggregation is not consolidation. Counterpart matching and explicit approved eliminations are prerequisites.',table(rowsOf(['related_party']),recordColumns,{recordClick:true}))}
function budget(){$('#content').innerHTML=banner()+card('Actual vs approved budget','Actuals require compatible complete accounting categories. Variance with zero budget shows N/A.',table(data.budget,[{key:'month'},{key:'branch_id',render:v=>esc(name('branch',v))},{key:'category_id'},{key:'amount',money:true},{key:'actual',money:true},{key:'variance',money:true},{key:'variance_percent',render:v=>v===null?'N/A':num(v)+'%'},{key:'owner'},{key:'comment'}],{recordClick:true}),'budget')+card('Scenario assumptions & approved commitments','Assumptions never overwrite historical records. Explicit links prevent counting the same obligation twice.',table(rowsOf(['forecast_assumption','commitment']),recordColumns,{recordClick:true}))+card('Explicit hospital economics scenarios','User-entered volumes, prices, deductions and cost drivers never replace historical actuals.',table(data.scenarios,[{key:'scenario_name'},{key:'patient_volume'},{key:'estimated_earned_revenue',money:true},{key:'estimated_operating_contribution',money:true},{key:'expected_collections',money:true},{key:'break_even_patients'},{key:'assumed_occupancy'}],{recordClick:true}))+`<div class="toolbar"><button id="economicsScenario">Add volume / pricing scenario</button><button class="primary" id="assumptionAdd">Add cash scenario assumption</button><button id="budgetAdd">Add monthly budget</button><button id="scenarioSettings">Configure delay / stress assumptions</button></div>`;$('#economicsScenario').onclick=()=>recordForm('finance_scenario');$('#assumptionAdd').onclick=()=>recordForm('forecast_assumption');$('#budgetAdd').onclick=()=>recordForm('budget');$('#scenarioSettings').onclick=()=>settingsForm()}
function exceptionTable(rows){return `<div class="table-wrap"><table class="plain-table"><thead><tr><th>Financial gap / expected vs observed</th><th>Type / severity</th><th>Exposure (may overlap)</th><th>Owner / due</th><th>Status</th><th>Evidence & action</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.category)}</strong><br>${esc(r.message)}${r.expected?`<br>Expected ${esc(r.expected)} · observed ${esc(r.observed)}`:''}</td><td>${badge(r.issue_kind,r.issue_kind==='missing_data'?'amber':'')}<br>${esc(r.severity)}</td><td class="number">${rupee(r.exposure)}</td><td>${esc(r.owner||'Unassigned')}<br>${date(r.due_date)}</td><td>${badge(r.status,r.status==='open'?'amber':'')}</td><td><button class="small" data-exception="${esc(r.key)}">Review / assign</button><button class="small" data-records="${r.record_ids.join(',')}">Evidence</button></td></tr>`).join('')||'<tr><td colspan="6">No detected items in this scope. Required source coverage must still be reviewed.</td></tr>'}</tbody></table></div>`}
function gaps(){$('#content').innerHTML=banner()+`<div class="notice">Missing-data issues, supported numerical differences and pattern/timing alerts are separate. Exposure can overlap across documents; these amounts are never summed into a claimed “total loss”.</div><div class="status-grid">${['missing_data','numerical_discrepancy','pattern_alert','timing_alert'].map(k=>`<div><h3>${data.exceptions.filter(x=>x.issue_kind===k).length}</h3><span class="fine">${k.replaceAll('_',' ')}</span></div>`).join('')}</div>`+card('Actionable financial exception register','Assign ownership, next-action due dates and resolution evidence; suppression and reopening are audited.',exceptionTable(data.exceptions),'exceptions')}
function reviewException(key){const r=data.exceptions.find(x=>x.key===key);modal('Review financial gap',`<div class="notice">${esc(r.message)}</div><form id="exceptionForm" class="form-grid"><label>Owner<input name="owner" value="${esc(r.owner)}"></label><label>Action due date<input type="date" name="due_date" value="${esc(r.due_date)}"></label><label>Status<select name="status">${options(['open','investigating','explained','resolved','suppressed'],r.status,null)}</select></label><label>Evidence / next action<textarea name="resolution">${esc(r.resolution)}</textarea></label><button class="primary">Save audited review</button></form>`);$('#exceptionForm').onsubmit=async e=>{e.preventDefault();try{await post('/api/exceptions',{...Object.fromEntries(new FormData(e.target)),key:r.key,branch_id:r.branch_id||filters.branch_id||'*'});$('#modal').close();navigate('gaps')}catch(err){toast(err.message,true)}}}
async function close(){const c=await api(scoped('/api/close')),reports=me.role==='management'||me.role==='finance'?await api(scoped('/api/reports')):[];$('#content').innerHTML=banner()+card('Month-end checklist','Independent sign-off requires evidence. A period can be locked only after its checklist is reviewed.',`<div class="table-wrap"><table><thead><tr><th>Period / branch</th><th>Control</th><th>Owner / due</th><th>Status / evidence</th><th>Action</th></tr></thead><tbody>${c.tasks.map(t=>`<tr><td>${esc(t.period)} · ${esc(name('branch',t.branch_id))}</td><td>${esc(t.title)}</td><td>${esc(t.owner)}<br>${date(t.due_date)}</td><td>${badge(t.status)}<br>${esc(t.evidence)}</td><td><button class="small" data-close-signoff="${t.id}" data-br="${esc(t.branch_id)}">Submit evidence for review</button></td></tr>`).join('')||'<tr><td colspan="5">Create a checklist for the selected branch/month.</td></tr>'}</tbody></table></div><div class="card-body"><form id="closeTaskForm" class="form-grid"><label>Branch<select name="branch_id">${options(master('branch'),filters.branch_id,null)}</select></label><label>Period<input name="period" type="month" value="${filters.end.slice(0,7)}" required></label><label>Checklist control<input name="title" required></label><label>Owner<input name="owner" required></label><label>Due date<input name="due_date" type="date"></label><button class="primary">Add checklist control</button></form></div>`)+card('Period locks & issued report versions','Previously issued reports remain immutable. New versions are explicitly restatements.',table(c.locks,[{key:'branch_id'},{key:'period'},{key:'locked'},{key:'version'}])+table(reports,[{key:'id'},{key:'version'},{key:'created'},{key:'filters'}])+`<div class="card-body toolbar"><button id="lockPeriod">Propose period lock</button><button id="reopenPeriod">Request authorised reopening</button><button class="primary" id="issueReport">Issue management report version</button></div>`);$('#closeTaskForm').onsubmit=async e=>{e.preventDefault();try{await post('/api/close',Object.fromEntries(new FormData(e.target)));navigate('close')}catch(err){toast(err.message,true)}};$$('[data-close-signoff]').forEach(b=>b.onclick=()=>sensitiveForm('close_signoff',{id:Number(b.dataset.closeSignoff)},b.dataset.br,'Add evidence for this checklist control.',true));$('#lockPeriod').onclick=()=>periodForm('period_lock');$('#reopenPeriod').onclick=()=>periodForm('period_reopen');$('#issueReport').onclick=async()=>{try{const r=await post('/api/reports?'+new URLSearchParams(filters));toast('Immutable report #'+r.id+' · version '+r.version);navigate('close')}catch(e){toast(e.message,true)}}}
function periodForm(action){modal(action==='period_lock'?'Propose period lock':'Request period reopening',`<form id="periodForm" class="form-grid"><label>Branch<select name="branch_id">${options(master('branch'),filters.branch_id,null)}</select></label><label>Period<input name="period" type="month" required value="${filters.end.slice(0,7)}"></label><label class="full">Reason / evidence<textarea name="notes" required></textarea></label><button class="primary">Submit for independent review</button></form>`);$('#periodForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await post('/api/change',{action,branch_id:f.branch_id,payload:{period:f.period},notes:f.notes});$('#modal').close();toast('Period change awaits independent review')}catch(err){toast(err.message,true)}}}
async function setup(){const tabs=['coverage','entry','import','masters','rules','approvals','access','metrics','audit'];if(!tabs.includes(moduleTab))moduleTab='coverage';$('#content').innerHTML=banner()+`<div class="tabs">${tabs.map(t=>`<button data-setup-tab="${t}" class="${moduleTab===t?'active':''}">${{coverage:'Data availability',entry:'In-app entry',import:'Import files',masters:'Organisation & masters',rules:'Rules & settings',approvals:'Approvals',access:'Access',metrics:'Metric dictionary',audit:'Audit trail'}[t]}</button>`).join('')}</div><div id="setupBody"></div>`;$$('[data-setup-tab]').forEach(b=>b.onclick=()=>{moduleTab=b.dataset.setupTab;navigate('setup')});if(moduleTab==='coverage')$('#setupBody').innerHTML=card('Data Setup · start with what you have','Every supported register is optional. Source availability is distinct from verified completeness.',table(data.data_setup.filter(r=>me.source_types[r.kind]),[{key:'name'},{key:'records'},{key:'coverage'},{key:'status'},{key:'missing_input'}]),'data_setup');else if(moduleTab==='entry')entrySetup();else if(moduleTab==='import')await importSetup();else if(moduleTab==='masters')mastersSetup();else if(moduleTab==='rules')await rulesSetup();else if(moduleTab==='approvals')await approvalsSetup();else if(moduleTab==='access')await accessSetup();else if(moduleTab==='metrics'){const m=await api('/api/metrics');$('#setupBody').innerHTML=card('Metric dictionary','Formula, date basis, authority and limitations for the management metrics.',table(m,[{key:'name'},{key:'formula'},{key:'basis'},{key:'source'},{key:'limitation'}]));}else if(moduleTab==='audit'){try{const a=await api('/api/audit');$('#setupBody').innerHTML=card('Audit trail · latest 500 events','Original source values are not rewritten by dashboard category changes.',table(a,[{key:'created'},{key:'user_id'},{key:'action'},{key:'target'},{key:'details'}]));}catch(e){$('#setupBody').innerHTML=`<div class="notice">${esc(e.message)}</div>`}}}
function entrySetup(){$('#setupBody').innerHTML=`<div class="notice info">Manual entries use the same canonical register fields as imports. Financial changes remain pending until a different authorised finance user approves them.</div><div class="add-row"><select id="entryKind">${options(Object.entries(me.source_types).map(([key,v])=>({key,name:v.name})),'billing',null)}</select><button class="primary" id="newRecord">Enter record</button><button id="downloadTemplate">Download empty import template</button></div>`+card('Current-period source registers','Click source evidence to inspect original fields; corrections require review.',table(data.records,recordColumns,{recordClick:true}),'records');$('#newRecord').onclick=()=>recordForm($('#entryKind').value);$('#downloadTemplate').onclick=()=>location.href='/api/templates/'+$('#entryKind').value}
function recordForm(kind){const contract=me.source_types[kind];modal('Enter '+contract.name,`<div class="notice info">${workspace==='demo'?'Synthetic demo':'Real records'} workspace. Required fields are marked. Choose the correct legal entity; it is not inferred from the branch.</div><form id="recordForm" class="form-grid">${Object.entries(contract.fields).map(([key,label])=>{const required=contract.required.includes(key);let input;const masterKind={entity_id:'entity',branch_id:'branch',department_id:'department',cost_centre_id:'cost_centre',panel_id:'panel',vendor_id:'vendor',bank_account_id:'bank_account',account_id:'account',employee_id:'employee',consultant_id:'consultant'}[key];if(masterKind)input=`<select name="${key}" ${required?'required':''}>${options(master(masterKind),filters[key]||'',required?'Choose '+masterKind:'Not supplied')}</select>`;else if(key==='notes')input=`<textarea name="${key}"></textarea>`;else input=`<input name="${key}" ${key==='date'||key.endsWith('_date')||key==='period_start'?'type="date"':key==='month'?'type="month"':'type="text"'} ${required?'required':''} ${key==='date'?`value="${today}"`:''} placeholder="${esc(label)}">`;return `<label>${esc(label)} ${required?'<span class="requirement-badge">Required</span>':''}${input}</label>`}).join('')}<label class="full">Evidence for reviewer<textarea id="manualEvidence" required></textarea></label><button class="primary">Propose financial entry</button></form>`);$('#recordForm').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k in values)if(values[k]==='')values[k]=null;try{await post('/api/records',{kind,fields:values,notes:$('#manualEvidence').value});$('#modal').close();toast('Record awaits independent finance review')}catch(err){toast(err.message,true)}}}
async function importSetup(){const history=await api('/api/imports');$('#setupBody').innerHTML=`<div class="notice">Imports always enter real records. Actual source files were not provided with either specification. No live Tally integration is claimed; structured Excel/CSV exports are supported through reviewed profiles.</div><section class="card"><div class="card-body"><form id="uploadForm" class="form-grid"><label>Real legal entity<select name="entity_id" id="uploadEntity" required></select></label><label>Real branch<select name="branch_id" id="uploadBranch" required></select></label><label>Source register<select name="kind">${options(Object.entries(me.source_types).map(([key,v])=>({key,name:v.name})),'journal',null)}</select></label><label>Excel / UTF-8 CSV<input type="file" name="file" accept=".xlsx,.csv" required></label><button class="primary" ${me.role==='reviewer'?'disabled':''}>Upload & inspect all worksheets</button></form><p class="fine">50 MB upload maximum; streaming/read-only workbook inspection. Add a legal entity and assign branches in Organisation & masters first.</p></div></section>`+card('Import history','File identity, branch/entity, period, uploader and processing results are retained.',`<div class="table-wrap"><table><thead><tr><th>File / register</th><th>Entity / branch</th><th>Period</th><th>Accepted / rejected / excluded</th><th>Status</th><th>Review</th></tr></thead><tbody>${history.map(r=>`<tr><td>#${r.id} ${esc(r.filename)}<br>${esc(me.source_types[r.kind]?.name||r.kind)}</td><td>${esc(r.entity_id)} · ${esc(r.branch_id)}</td><td>${r.review.period?.map(date).join(' – ')||'Not reviewed'}</td><td>${r.review.accepted_count??'—'} / ${r.review.rejected_count??'—'} / ${r.review.excluded_count??'—'}</td><td>${badge(r.state)}</td><td><button data-import="${r.id}" class="small">Inspect / map</button></td></tr>`).join('')||'<tr><td colspan="6">No real source files imported.</td></tr>'}</tbody></table></div>`);const realMasters=await api('/api/masters?workspace=real');$('#uploadEntity').innerHTML=options(realMasters.filter(x=>x.kind==='entity'),'','Choose legal entity');$('#uploadBranch').innerHTML=options(realMasters.filter(x=>x.kind==='branch'),'','Choose branch');$('#uploadForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await api('/api/imports/upload',{method:'POST',body:new FormData(e.target)});toast(r.duplicate?r.message:'File staged; review mappings');await openImport(r.id)}catch(err){toast(err.message,true)}finally{button.disabled=false}}}
async function openImport(id){try{const imp=await api('/api/imports/'+id),contract=me.source_types[imp.kind];if(['committed','superseded','rolled_back'].includes(imp.state)){modal('Import #'+id+' · '+imp.filename,`<p>${esc(imp.entity_id)} · ${esc(imp.branch_id)} · ${badge(imp.state)}</p>${importSummary(imp.review)}<details open><summary>Versioned approved mapping</summary><pre>${esc(JSON.stringify(imp.mapping,null,2))}</pre></details><div class="toolbar"><button id="reprocessImport">Stage corrected mapping revision</button><button id="rollbackImport">Safe rollback</button><a href="/api/imports/${id}/rejected.csv">Download rejected rows</a></div>`);$('#reprocessImport').onclick=async()=>{try{const r=await api('/api/imports/'+id+'/reprocess',{method:'POST'});openImport(r.id)}catch(e){toast(e.message,true)}};$('#rollbackImport').onclick=()=>{modal('Rollback import #'+id,`<div class="notice">The original file, records and audit trail are retained. Linked allocations/matches and locked periods block rollback.</div><form id="rollbackForm"><label>Reason<textarea name="notes" required></textarea></label><button class="primary">Rollback only this import</button></form>`);$('#rollbackForm').onsubmit=async e=>{e.preventDefault();try{await post('/api/imports/'+id+'/rollback',Object.fromEntries(new FormData(e.target)));$('#modal').close();navigate('setup')}catch(err){toast(err.message,true)}}};return}
const sheets=imp.review.inspection||[],profiles=(await api('/api/profiles')).filter(x=>x.kind===imp.kind);modal('Review '+contract.name+' · '+imp.filename,`<p class="fine">${esc(imp.entity_id)} · ${esc(imp.branch_id)} · all worksheets inspected. Financial field meanings require review.</p><label>Reusable mapping profile<select id="mappingProfile">${options(profiles.map(p=>({key:String(p.id),name:p.name+' · version '+p.version})),'','Manual mapping')}</select></label><form id="mappingForm">${sheets.map(s=>{const old=imp.mapping.sheets?.[s.name]||{};return `<section class="sheet-section" data-sheet="${esc(s.name)}"><div class="split"><label><input type="checkbox" class="sheetEnabled" ${old.enabled===false?'':'checked'}> ${esc(s.name)}</label><span class="fine">${s.nonblank_rows} nonblank rows</span></div><label style="width:180px">Header row<input class="headerRow" type="number" min="1" value="${old.header_row||s.header_row_candidate}" required></label><button type="button" class="small" data-refresh-header>Refresh labels from sample row</button><details><summary>Original worksheet sample, titles and metadata</summary><div class="table-wrap"><table><tbody>${s.sample.map(r=>`<tr><td>Row ${r.row}</td>${r.cells.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>${Object.entries(contract.fields).map(([key,label])=>`<div class="mapping-row"><span>${esc(label)} ${contract.required.includes(key)?'<span class="requirement-badge">Required</span>':''}</span><select data-field="${key}"><option value="">${['entity_id','branch_id'].includes(key)?'Use selected import scope':'Unmapped / unavailable'}</option>${s.columns.map((v,j)=>`<option value="${j}" ${String(old.columns?.[key])===String(j)?'selected':''}>${j+1}. ${esc(v||'(blank)')}</option>`).join('')}</select></div>`).join('')}</section>`}).join('')}<label>Save as profile name (optional)<input id="profileName" value="${esc(imp.mapping.profile_name||'')}"></label><div class="notice">Amount semantics differ by register: final bill net, supplier invoice liability, actual cash movement, stock cost and journal debit/credit are not interchangeable. Signed returns, units and snapshot versus movement definitions must be validated. Map UHID/admission as strings.</div><label><input id="mappingReviewed" type="checkbox" required> I reviewed the fields, date basis, signs, amounts and identifiers; no financial semantics are inferred.</label><button class="primary" style="margin:18px 0">Validate reviewed mapping</button></form><div id="importResult"></div>`);function applyProfile(mapping){$$('[data-sheet]').forEach(box=>{const cfg=mapping.sheets?.[box.dataset.sheet];if(!cfg)return;box.querySelector('.headerRow').value=cfg.header_row;box.querySelector('.sheetEnabled').checked=cfg.enabled!==false;box.querySelectorAll('[data-field]').forEach(select=>select.value=cfg.columns?.[select.dataset.field]??'')})}$('#mappingProfile').onchange=e=>{const p=profiles.find(x=>String(x.id)===e.target.value);if(p){applyProfile(p.mapping);$('#profileName').value=p.name}};$$('[data-refresh-header]').forEach(b=>b.onclick=()=>{const box=b.closest('[data-sheet]'),s=sheets.find(x=>x.name===box.dataset.sheet),row=s.sample.find(r=>r.row===Number(box.querySelector('.headerRow').value));if(!row){toast('This header is outside the inspected sample; use explicit column positions and verify the workbook.',true);return}box.querySelectorAll('[data-field]').forEach(select=>{const chosen=select.value;select.innerHTML='<option value="">Unmapped / scope selection</option>'+row.cells.map((v,j)=>`<option value="${j}" ${chosen===String(j)?'selected':''}>${j+1}. ${esc(v||'(blank)')}</option>`).join('')})});$('#mappingForm').onsubmit=async e=>{e.preventDefault();const mapping={reviewed:$('#mappingReviewed').checked,profile_name:$('#profileName').value,sheets:{}};$$('[data-sheet]').forEach(box=>mapping.sheets[box.dataset.sheet]={enabled:box.querySelector('.sheetEnabled').checked,header_row:Number(box.querySelector('.headerRow').value),columns:Object.fromEntries([...box.querySelectorAll('[data-field]')].filter(x=>x.value!=='').map(x=>[x.dataset.field,x.value]))});try{const r=await api('/api/imports/'+id+'/review',{method:'POST',body:JSON.stringify(mapping)});$('#importResult').innerHTML=importSummary(r)+`<form id="commitForm" class="stack">${r.overlaps.map(x=>`<label><input type="checkbox" name="replace" value="${x.id}"> Replace entire import #${x.id}: ${esc(x.filename)}</label>`).join('')}${r.overlaps.length?'<label><input type="checkbox" name="retain"> Explicitly retain all overlapping rows; no silent transaction deduplication.</label>':''}<label>Audit note<textarea name="notes"></textarea></label><button class="primary">Commit ${r.accepted_count} accepted records to real workspace</button></form>`;$('#commitForm').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target);try{await api('/api/imports/'+id+'/commit',{method:'POST',body:JSON.stringify({replace_ids:f.getAll('replace').map(Number),retain_overlap:f.has('retain'),notes:f.get('notes')})});$('#modal').close();workspace='real';$('#workspaceMode').value=workspace;toast('Import committed without changing original source rows');navigate('setup')}catch(err){toast(err.message,true)}}}catch(err){toast(err.message,true)}}}catch(e){toast(e.message,true)}}
function importSummary(r){return `<div class="metric-grid"><div class="metric"><div class="metric-label">Accepted</div><div class="metric-value">${r.accepted_count??'—'}</div></div><div class="metric"><div class="metric-label">Rejected / excluded</div><div class="metric-value">${r.rejected_count??'—'} / ${r.excluded_count??'—'}</div></div><div class="metric"><div class="metric-label">Mapped amount total</div><div class="metric-value">${rupee(r.net_total)}</div><p class="fine">Register-specific semantics; not universal revenue</p></div><div class="metric"><div class="metric-label">Detected period</div><p>${r.period?.map(date).join(' – ')||'Unknown'}</p></div></div><details><summary>Accepted samples, rejected rows and exclusions</summary><pre>${esc(JSON.stringify({preview:r.preview,rejected:r.rejected,excluded:r.excluded},null,2))}</pre></details>`}
function mastersSetup(){$('#setupBody').innerHTML=card('Organisation and financial masters','Legal entities and branches are separate. New masters and vendor bank changes require independent approval.',`<div class="card-body"><form id="masterForm" class="form-grid"><label>Master type<select name="kind" id="masterKind">${options(me.master_types,'entity',null)}</select></label><label>Stable key<input name="key" required placeholder="e.g. entity-navin"></label><label>Name<input name="name" required></label><label>Branch scope<select name="branch_id">${options([{key:'*',name:'Group master'},...master('branch')],'*',null)}</select></label><label>Entity assignment / account category / approval properties<textarea name="properties" id="masterProperties" placeholder='{"entity_id":"entity-navin"}'>{}</textarea></label><label>Evidence for reviewer<textarea name="notes" required></textarea></label><button class="primary">Propose new / revised master</button></form><p class="fine">Branch properties: {"entity_id":"entity-key"}. Account: {"statement_category":"revenue"}. Vendor: {"approved":true}; banking changes are reviewed. Other master properties stay available for explicit rules.</p></div>`+table(masterData,[{key:'kind'},{key:'key'},{key:'name'},{key:'properties'},{key:'version'}]));$('#masterKind').onchange=e=>$('#masterProperties').value=JSON.stringify(e.target.value==='account'?{statement_category:'revenue'}:e.target.value==='branch'?{entity_id:''}:e.target.value==='vendor'?{approved:false}:{});$('#masterForm').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));b.properties=JSON.parse(b.properties);await post('/api/masters',b);toast('Master change awaits independent review')}catch(err){toast(err.message,true)}}}
async function rulesSetup(){const rules=await api(scoped('/api/rules'));$('#setupBody').innerHTML=card('Reviewed effective-dated rules','Contract bases, exclusions and allocation drivers must be explicit. No legal tax rates or deadlines are seeded.',table(rules,[{key:'id'},{key:'kind'},{key:'branch_id'},{key:'fields'},{key:'version'}])+`<div class="card-body toolbar">${['consultant','shared_cost','tariff','panel_terms','elimination'].map(k=>`<button data-new-rule="${k}">Add ${k.replaceAll('_',' ')} rule</button>`).join('')}<button id="configureSettings">Configure financial settings</button><button id="retireRule">Retire a rule by ID</button></div>`)+card('Current reviewed financial settings','Changes are versioned and need independent review.',table(Object.entries(data.settings).map(([key,value])=>({key,value})),[{key:'key'},{key:'value'}]));$$('[data-new-rule]').forEach(b=>b.onclick=()=>ruleForm(b.dataset.newRule));$('#configureSettings').onclick=settingsForm;$('#retireRule').onclick=()=>sensitiveForm('rule_retire',{id:null},'*','Enter an active rule ID to retire its version.')}
function ruleForm(kind){const examples={consultant:{consultant_id:'',basis:'percent',base_kind:'collected',rate:'',ceiling:null,start:today,end:today,notes:''},shared_cost:{amount:'',driver:'revenue',branches:master('branch').map(b=>b.key),weights:{},start:today,end:today,notes:''},tariff:{code:'',rate:'',start:today,end:today,notes:''},panel_terms:{panel_id:'',submission_days:null,response_days:null,payment_days:null,start:today,end:today,notes:''},elimination:{counterpart_reference:'',account_id:'',start:today,end:today,notes:''}};modal('Reviewed '+kind.replaceAll('_',' ')+' rule',`<div class="notice info">Use exact keys and effective dates. Consultant percentage bases must explicitly be billed or collected. Shared-cost allocations retain unallocated amounts if the driver is missing. Elimination rules do not create consolidated statements without matched counterpart records.</div><form id="ruleForm" class="stack"><label>Branch scope<select name="branch_id">${options([{key:'*',name:'Group'},...master('branch')],filters.branch_id||'*',null)}</select></label><label>Rule fields<textarea name="fields" rows="12" required>${esc(JSON.stringify(examples[kind],null,2))}</textarea></label><label>Approval reason<input name="notes" required></label><button class="primary">Propose effective-dated rule</button></form>`);$('#ruleForm').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));await post('/api/change',{action:'rule',branch_id:f.branch_id,payload:{kind,fields:JSON.parse(f.fields)},notes:f.notes});$('#modal').close();toast('Rule awaits independent review')}catch(err){toast(err.message,true)}}}
function settingsForm(){modal('Reviewed metric and policy settings',`<div class="notice">Only attest complete accounting/opening/credit-revenue coverage after reconciling the actual source scope. Materiality and deadlines are user-approved, not universal assumptions. Demo settings never affect real records.</div><form id="settingsForm" class="stack"><label>Financial settings<textarea name="settings" rows="14">${esc(JSON.stringify(data.settings,null,2))}</textarea></label><label>Evidence / review reason<textarea name="notes" required></textarea></label><button class="primary">Propose settings revision</button></form>`);$('#settingsForm').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));await post('/api/change',{action:'setting',branch_id:'*',payload:JSON.parse(f.settings),notes:f.notes});$('#modal').close();toast('Settings revision awaits independent review')}catch(err){toast(err.message,true)}}}
function sensitiveForm(action,payload,branch_id,description,evidence=false){modal('Request '+action.replaceAll('_',' '),`<div class="notice">${esc(description)} Maker cannot approve their own change.</div><form id="changeForm" class="stack"><label>Change parameters<textarea name="payload" rows="4">${esc(JSON.stringify(payload,null,2))}</textarea></label>${evidence?'<label>Supporting evidence<textarea name="evidence" required></textarea></label>':''}<label>Review reason<textarea name="notes" required></textarea></label><button class="primary">Submit for independent approval</button></form>`);$('#changeForm').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),p=JSON.parse(f.payload);if(evidence)p.evidence=f.evidence;await post('/api/change',{action,branch_id,payload:p,notes:f.notes});$('#modal').close();toast('Change awaits a different authorised reviewer')}catch(err){toast(err.message,true)}}}
async function approvalsSetup(){const proposals=await api(scoped('/api/proposals'));$('#setupBody').innerHTML=`<div class="notice info">Two-person control: makers cannot review their own changes. Create a separate authorised finance user in Access, then sign in as that user to approve. No payments or external accounting posts are executed.</div>${proposals.map(p=>`<section class="approval-item"><div class="split"><h3>#${p.id} · ${esc(p.action.replaceAll('_',' '))}</h3>${badge(p.status,p.status==='pending'?'amber':'')}</div><p class="fine">Maker #${p.maker} · ${esc(p.branch_id)} · ${esc(p.workspace)} · ${esc(p.created)} UTC</p><details><summary>Proposed change evidence</summary><pre>${esc(JSON.stringify(p.payload,null,2))}</pre></details>${p.status==='pending'&&p.maker!==me.id&&['management','finance'].includes(me.role)?`<form data-review="${p.id}" class="form-grid"><label>Reviewer evidence / note<input name="notes" required></label><label>Decision<select name="decision"><option value="approved">Approve</option><option value="rejected">Reject</option></select></label><button class="primary">Record independent decision</button></form>`:p.status==='pending'?'<p class="fine">Awaiting a different authorised finance reviewer.</p>':`<p class="fine">Reviewer #${p.reviewer} · ${esc(p.review_note)}</p>`}</section>`).join('')||'<div class="empty-hero"><h3>No pending financial changes</h3><p>Manual records, allocations, write-offs, bank matches and period changes appear here before independent approval.</p></div>'}`;$$('[data-review]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await post('/api/proposals/'+form.dataset.review+'/review',Object.fromEntries(new FormData(form)));toast('Reviewer decision recorded');navigate('setup')}catch(err){toast(err.message,true)}})}
async function accessSetup(){let users=[];if(me.role==='management')users=await api('/api/users');$('#setupBody').innerHTML=card('Users and branch/role permissions','Server enforcement covers registers, exports and direct API requests. Payroll is limited to finance/management.',table(users,[{key:'username'},{key:'role'},{key:'branches'},{key:'active'}])+`<div class="card-body"><form id="userForm" class="form-grid"><label>Username<input name="username" required autocomplete="off"></label><label>Temporary password<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label>Role<select name="role">${options(me.roles,'finance',null)}</select></label><label>Authorised branch keys (comma separated, * for group)<input name="branches" value="${me.branches.join(',')}" required></label><button class="primary" ${me.role!=='management'?'disabled':''}>Create authorised user</button></form><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><form id="passwordForm" class="form-grid"><label>Current password<input name="old" type="password" required autocomplete="current-password"></label><label>New password<input name="new" type="password" minlength="12" required autocomplete="new-password"></label><button>Change password and sign out</button></form></div>`);$('#userForm').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));b.branches=b.branches.split(',').map(s=>s.trim()).filter(Boolean);await post('/api/users',b);toast('User created with branch and role restrictions');e.target.reset();navigate('setup')}catch(err){toast(err.message,true)}};$('#passwordForm').onsubmit=async e=>{e.preventDefault();try{await post('/api/password',Object.fromEntries(new FormData(e.target)));showLogin();$('#modal').close()}catch(err){toast(err.message,true)}}}
start();
